use genex::prelude::*;

/// A window as an opening, not a picture: jambs, head and sill frame a reveal, the glazing sits back from the face.
const REVEAL: f32 = 0.14;

fn draw_window(frame: &mut Frame, centre: Vec3, facing_yaw: f32, w: f32, h: f32, wall: &Material, frame_mat: &Material, glass: &Material) {
    let turn = Quat::from_rotation_y(facing_yaw);
    let at = |local: Vec3| centre + turn * local;
    let piece = |local: Vec3, size: Vec3| Transform::from_translation(at(local)).with_rotation(turn).with_scale(size);
    frame.tag("window");
    // Reveal: four returns of the wall's own material, REVEAL deep.
    frame.cube_with(piece(vec3(-w * 0.5, 0.0, -REVEAL * 0.5), vec3(0.06, h, REVEAL)), wall);
    frame.cube_with(piece(vec3(w * 0.5, 0.0, -REVEAL * 0.5), vec3(0.06, h, REVEAL)), wall);
    frame.cube_with(piece(vec3(0.0, h * 0.5, -REVEAL * 0.5), vec3(w, 0.06, REVEAL)), wall);
    frame.cube_with(piece(vec3(0.0, -h * 0.5 - 0.03, 0.04), vec3(w + 0.12, 0.05, REVEAL + 0.1)), frame_mat); // the sill sticks out
    // The glazing set back, and a blown-out pane glows: pair it with a spot shining in (docs/api/lighting.md).
    frame.cube_with(piece(vec3(0.0, 0.0, -REVEAL), vec3(w, h, 0.01)), glass);
    frame.tag("seam");
    frame.cube_with(piece(vec3(0.0, h * 0.5 + 0.45, 0.005), vec3(w + 1.6, 0.03, 0.02)), frame_mat);
}
